/* Raw traction isolates the proposed regional load from rigid projection. */
static int localized_profile_contract(void){
 belt_v rear_top=belt_whale_raw(1,1,-.65,.4),rear_bottom=belt_whale_raw(1,1,-.65,-.4);
 belt_v front_top=belt_whale_raw(1,1,.35,.4),front_bottom=belt_whale_raw(1,1,.35,-.4);
 double rear_slope=(rear_top.y-rear_bottom.y)/.8,front_slope=(front_top.y-front_bottom.y)/.8;
 CHECK(rear_slope<-3.5&&front_slope>0&&front_slope<.4&&-rear_slope>10*front_slope);CHECK(rear_top.x<-.15&&front_top.x==0);
 for(int i=0;i<=64;++i){double x=-1+2.0*i/64;belt_v top=belt_whale_raw(1,1,x,.4),bottom=belt_whale_raw(1,1,x,-.4),mirror=belt_whale_raw(1,-1,-x,.4);
  double slope=(top.y-bottom.y)/.8;CHECK(fabs(top.x+mirror.x)<1e-14&&fabs(top.y-mirror.y)<1e-14);
  if(x>=-.15)CHECK(slope>=-1e-14);if(x<=-.75)CHECK(fabs(slope+4)<1e-13);if(x>=.60)CHECK(fabs(slope-.40)<1e-13);
  belt_v zero=belt_whale_raw(1,0,x,.4),tiny=belt_whale_raw(1,1e-9,x,.4),negative=belt_whale_raw(1,-1e-9,x,.4);CHECK(zero.x==0&&zero.y==0);CHECK(hypot(tiny.x,tiny.y)<2e-9&&hypot(negative.x,negative.y)<2e-9);}
 const double boundaries[4]={-.75,-.15,.05,.60},eps=1e-6;
 for(int i=0;i<4;++i){double x=boundaries[i];belt_v left=belt_whale_raw(1,1,x-eps,.4),center=belt_whale_raw(1,1,x,.4),right=belt_whale_raw(1,1,x+eps,.4);
  CHECK(hypot(left.x-right.x,left.y-right.y)<1e-5);CHECK(fabs((right.x-center.x)/eps-(center.x-left.x)/eps)<1e-4);CHECK(fabs((right.y-center.y)/eps-(center.y-left.y)/eps)<1e-4);}
 printf("rear-localized raw profile, weak front support, mirror, C1 boundaries and zero crossing PASS rearSlope=%.17g frontSlope=%.17g\n",rear_slope,front_slope);return 0;
}
